import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent, type Skill } from "../../../types";
import { OrderedBlockEvent } from "./OrderedBlockEvent";

const skill: Skill = {
  id: "travel_notice",
  name: "Travel Notice",
  description: null,
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [],
  blocks: {},
  referenced_skills: [],
  tool_names: [],
  hidden: false,
};

function makeEvent(
  eventType: ConversationEventType = ConversationEventType.OrderedBlockEntered,
  skillId = "travel_notice",
  blockId = "submit",
): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: "1",
    conversationEventType: eventType,
    skillId,
    blockId,
    name: eventType.toLowerCase(),
    timestamp: new Date().toISOString(),
    originalTimestamp: 0,
    metadata: { parseData: {} },
  };
}

describe("OrderedBlockEvent", () => {
  it("renders the catalog skill name and entered verb", () => {
    renderWithProviders(<OrderedBlockEvent event={makeEvent()} isSelected={false} />, {
      initialStoreState: { skillCatalog: { travel_notice: skill } },
    });

    expect(screen.getByText("Travel Notice")).toBeInTheDocument();
    expect(screen.getByText("submit")).toBeInTheDocument();
    expect(screen.getByText(/skill \/.*block entered/)).toBeInTheDocument();
  });

  it("falls back to the skill id when the catalog has no entry", () => {
    renderWithProviders(<OrderedBlockEvent event={makeEvent()} isSelected={false} />, {
      initialStoreState: { skillCatalog: {} },
    });

    expect(screen.getByText("travel_notice")).toBeInTheDocument();
    expect(screen.getByText("submit")).toBeInTheDocument();
    expect(screen.getByText(/skill \/.*block entered/)).toBeInTheDocument();
  });

  it.each([
    [ConversationEventType.OrderedBlockCompleted, "completed"],
    [ConversationEventType.OrderedBlockCancelled, "cancelled"],
    [ConversationEventType.OrderedBlockInterrupted, "interrupted"],
    [ConversationEventType.OrderedBlockResumed, "resumed"],
  ])("renders the %s verb", (eventType, verb) => {
    renderWithProviders(<OrderedBlockEvent event={makeEvent(eventType)} isSelected={false} />, {
      initialStoreState: { skillCatalog: { travel_notice: skill } },
    });

    expect(screen.getByText(new RegExp(`block ${verb}`))).toBeInTheDocument();
  });
});
